stageCss:
#stage .t-scene{ position:relative; width:100%; height:100%; }#stage .t-hook{
  position:absolute; inset:0; z-index:6; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:10px; text-align:center;
  opacity:0; transform:scale(.97); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}#stage .t-hook.on{ opacity:1; transform:none; }#stage .t-hook-l1{ color:var(--text-dim); font-size:40px; font-weight:600; }#stage .t-hook-big{
  color:#fff; font-size:210px; font-weight:900; line-height:1; letter-spacing:-9px;
  text-shadow:0 0 80px rgba(58,160,255,.45);
}#stage .t-hook-l2{ color:var(--accent-1); font-size:34px; font-weight:700; margin-top:14px; }#stage .t-runbar{ position:absolute; top:0; left:0; width:992px; height:58px; display:flex; align-items:center; gap:16px; }#stage .t-runbadge{
  padding:10px 22px; border-radius:100px; background:rgba(58,160,255,.16);
  border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:24px; font-weight:700; letter-spacing:1px;
}#stage .t-runstate{ color:var(--text-dim); font-family:var(--font-mono); font-size:22px; }#stage .t-editor{ position:absolute; top:78px; left:0; width:992px; height:414px; }#stage .t-editor .bar{ position:relative; }#stage .t-file{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; margin-left:14px; }#stage .t-editor .body{ font-size:26px; line-height:1.72; }#stage .t-line{ opacity:0; transform:translateX(-10px); transition:opacity .26s ease, transform .26s ease; position:relative; }#stage .t-line.show{ opacity:1; transform:none; }#stage .t-line.replayed{ opacity:.4; }#stage .t-line.executing{
  background:rgba(58,160,255,.14); border-radius:8px;
  box-shadow:inset 3px 0 0 var(--accent-1);
}#stage .t-mark{ display:inline-block; width:34px; }#stage .t-line.replayed .t-mark::after{ content:"\2713"; color:var(--success); font-weight:700; margin-left:12px; }#stage .t-line.executing .t-mark::after{ content:"\25B6"; color:var(--accent-1); margin-left:12px; }#stage .t-stopped{
  position:absolute; right:22px; bottom:18px; padding:9px 20px; border-radius:10px;
  background:rgba(244,74,106,.16); border:1.5px solid rgba(244,74,106,.5);
  color:var(--danger); font-family:var(--font-mono); font-size:21px; font-weight:700;
  opacity:0; transition:opacity .24s ease;
}#stage .t-stopped.on{ opacity:1; }#stage .t-panelbox{ position:absolute; top:524px; left:0; width:992px; height:300px; }#stage .t-panel{
  position:absolute; inset:0; padding:26px 30px; opacity:0; transform:scale(.98);
  pointer-events:none; transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}#stage .t-panel.on{ opacity:1; transform:none; }#stage .t-hist{ margin-top:14px; display:flex; flex-direction:column; gap:8px; }#stage .t-hrow{
  display:flex; align-items:center; gap:18px; padding:9px 16px; border-radius:10px;
  background:rgba(20,27,43,.7); border:1px solid var(--border);
  font-family:var(--font-mono); font-size:22px;
  opacity:0; transform:translateY(8px); transition:opacity .24s ease, transform .24s ease;
}#stage .t-hrow.on{ opacity:1; transform:none; }#stage .t-ev{ color:var(--accent-cyan); min-width:250px; }#stage .t-ev.t-ok{ color:var(--success); }#stage .t-nm{ color:var(--text-primary); min-width:150px; }#stage .t-vl{ color:var(--text-dim); margin-left:auto; }#stage .t-trap{ margin-top:14px; display:flex; flex-direction:column; gap:9px; }#stage .t-trow{ display:flex; align-items:center; gap:22px; font-family:var(--font-mono); font-size:25px; }#stage .t-run{ color:var(--text-dim); min-width:110px; }#stage .t-val{ color:var(--danger); font-weight:700; }#stage .t-trapnote{ color:var(--text-dim); font-size:23px; margin-top:16px; }#stage .t-fix{ margin-top:14px; display:flex; flex-direction:column; gap:11px; }#stage .t-frow{ display:flex; align-items:center; gap:16px; font-family:var(--font-mono); font-size:23px; }#stage .t-frow code{ color:var(--text-primary); }#stage .t-frow .t-note{ color:var(--text-dim); font-size:20px; margin-left:auto; }#stage .t-bad code{ color:var(--danger); }#stage .t-good code{ color:var(--success); }#stage .t-x{ color:var(--danger); font-size:28px; font-weight:800; width:26px; }#stage .t-c{ color:var(--success); font-size:26px; font-weight:800; width:26px; }#stage .t-foot{ position:absolute; top:854px; left:0; width:992px; display:flex; gap:18px; }#stage .t-stat{ flex:1; padding:22px 24px; text-align:center; }#stage .t-stat-v{ font-size:54px; font-weight:800; line-height:1; }#stage .t-stat-l{ color:var(--text-dim); font-size:19px; font-weight:600; margin-top:10px; }

stages.js:
MSD.cls('#t-hook', 'on', false);
MSD.qa('#t-editor .t-line').forEach(function(el, i){
  MSD.after(60 + i * 85, function(){ el.classList.add('show'); MSD.sfx.tick(); });
});
MSD.after(760, function(){ MSD.sfx.sparkle(); });

MSD.cls('#t-editor .t-line', 'show', true);
MSD.focus('#t-editor', '.t-panelbox');
MSD.after(150, function(){ MSD.cls('#t-l3', 'executing', true); MSD.sfx.blip(2); });
MSD.after(900, function(){
  MSD.cls('#t-l3', 'executing', false);
  MSD.cls('#t-stopped', 'on', true);
  MSD.shake('#t-editor');
  MSD.q('#t-runstate').textContent = 'exited';
});

MSD.cls('#t-editor .t-line', 'show', true);
MSD.cls('#t-stopped', 'on', false);
MSD.focus('.t-panelbox', '#t-editor');
MSD.cls('#t-p-history', 'on', true);
MSD.cls('#t-p-history', 'msd-scan', true);
MSD.after(150, function(){ MSD.cls('#t-h1', 'on', true); MSD.sfx.blip(0); });
MSD.after(620, function(){ MSD.cls('#t-h2', 'on', true); MSD.sfx.blip(2); });
MSD.after(1150, function(){ MSD.cls('#t-p-history', 'msd-scan', false); MSD.flash('#t-p-history'); MSD.sfx.lock(); });

MSD.cls('#t-editor .t-line', 'show', true);
MSD.cls('#t-h1, #t-h2', 'on', true);
MSD.cls('#t-p-history', 'on', true);
MSD.focus('#t-editor', '.t-panelbox');
MSD.after(120, function(){
  MSD.q('#t-runbadge').textContent = 'RUN #2';
  MSD.q('#t-runstate').textContent = 'replaying';
  MSD.punch('#t-runbadge', 3);
});
MSD.after(560, function(){ MSD.cls('#t-l3', 'replayed', true); MSD.sfx.step(1); });
MSD.after(1000, function(){ MSD.cls('#t-l4', 'executing', true); MSD.sfx.blip(3); });
MSD.after(1700, function(){ MSD.cls('#t-h3', 'on', true); MSD.sfx.data(1); });

MSD.cls('#t-editor .t-line', 'show', true);
MSD.cls('#t-p-history', 'on', true);
MSD.cls('#t-h1, #t-h2, #t-h3', 'on', true);
MSD.cls('#t-l3', 'replayed', true);
MSD.focus('#t-editor', '.t-panelbox');
MSD.after(120, function(){
  MSD.q('#t-runbadge').textContent = 'RUN #3';
  MSD.punch('#t-runbadge', 4);
  MSD.cls('#t-l4', 'executing', false);
  MSD.cls('#t-l4', 'replayed', true);
  MSD.sfx.step(2);
});
MSD.after(620, function(){ MSD.cls('#t-l5', 'executing', true); MSD.sfx.blip(4); });
MSD.after(1100, function(){ MSD.cls('#t-h4', 'on', true); MSD.sfx.data(2); });
MSD.after(1600, function(){ MSD.sfx.sparkle(); });

MSD.cls('#t-editor .t-line', 'show', true);
MSD.cls('#t-l3, #t-l4', 'replayed', true);
MSD.cls('#t-p-history', 'on', false);
MSD.focus('.t-panelbox', '#t-editor');
MSD.cls('#t-p-trap', 'on', true);
MSD.qa('#t-p-trap .t-trow').forEach(function(el, i){
  MSD.after(180 + i * 240, function(){ MSD.punch('#t-p-trap .t-trow:nth-child(' + (i + 1) + ')', i); });
});
MSD.after(1150, function(){ MSD.shake('#t-p-trap'); MSD.sfx.error(); });

MSD.unfocus();
MSD.cls('#t-editor .t-line', 'show', true);
MSD.cls('#t-l3, #t-l4, #t-l5', 'replayed', true);
MSD.cls('#t-p-trap', 'on', false);
MSD.cls('#t-p-fix', 'on', true);
MSD.q('#t-runbadge').textContent = 'RUN #14';
MSD.q('#t-runstate').textContent = 'completed';
MSD.show('.t-stat', 95, true);
MSD.after(140, function(){ MSD.count('#t-v1', 14, 520); MSD.sfx.blip(1); });
MSD.after(360, function(){ MSD.count('#t-v2', 3, 420); MSD.sfx.blip(3); });
MSD.after(580, function(){ MSD.count('#t-v3', 1, 380); MSD.sfx.blip(5); });
MSD.after(1050, function(){ MSD.flash('.t-stat'); MSD.sfx.sparkle(); });
